parameters.script:
// ================= 主趋势线监控 =================
// 通达信原式:  主趋势线: EMA(EMA(CLOSE,10),10)
//              红(买) = 今日主趋势线 > 昨日 ;  绿(卖) = 其余
// 只需要收盘价序列，其余 HG 变量（MACD 背离、筹码、共振、打板/低吸）都不参与主趋势线。

var CODE   = "sh600000";   // 标的，必须带前缀：sh / sz / bj
var PERIOD = "day";        // "day" 日线监控 / "week" 周线监控
var BARS   = 150;          // 参与计算的 K 线根数，越多 EMA 越接近通达信
var ONLY_NEW_SIGNAL = true;   // true = 只在方向翻转时通知；false = 每次都报当前状态

// 数据源顺序：腾讯 → 东方财富 → 新浪，前一个失败自动换下一个
// 注意：新浪盘中不返回当日 K 线，会慢一根，只作兜底

function normCode(c) {
    c = String(c).toLowerCase().replace(/\s/g, "");
    if (c.indexOf("sh") === 0 || c.indexOf("sz") === 0 || c.indexOf("bj") === 0) return c;
    if (c.length !== 6) return c;
    var h = c.charAt(0);
    if (h === "6" || h === "5" || h === "9") return "sh" + c;
    if (h === "4" || h === "8") return "bj" + c;
    return "sz" + c;   // 0/1/2/3 开头；指数请显式写前缀
}

// 通达信 EMA: 首值取第一根收盘价，之后 alpha = 2/(N+1)
function ema(vals, n) {
    var a = 2.0 / (n + 1);
    var out = [vals[0]];
    for (var i = 1; i < vals.length; i++) out.push(out[i - 1] + a * (vals[i] - out[i - 1]));
    return out;
}

function kTencent(code, period, n) {
    var p = period === "week" ? "week" : "day";
    var url = "https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param="
            + code + "," + p + ",,," + n + ",qfq";
    var r = vflow.network.http_request({ url: url, method: "GET", timeout: 10 });
    var o = JSON.parse(String(r.response_body));
    var node = o.data[code];
    var arr = node["qfq" + p] || node[p];
    if (!arr || !arr.length) throw "腾讯无数据";
    var out = [];
    for (var i = 0; i < arr.length; i++) out.push(parseFloat(arr[i][2]));   // [日期,开,收,高,低,量]
    return out;
}

function kEastmoney(code, period, n) {
    var secid = (code.indexOf("sh") === 0 ? "1." : "0.") + code.substring(2);
    var klt = period === "week" ? 102 : 101;
    var url = "https://push2his.eastmoney.com/api/qt/stock/kline/get?secid=" + secid
            + "&ut=fa5fd1943c7b386f172d6893dbfba10b&klt=" + klt + "&fqt=1&end=20500101"
            + "&lmt=" + n + "&fields1=f1,f2,f3,f4,f5,f6&fields2=f51,f52,f53,f54,f55,f56,f57,f58";
    var r = vflow.network.http_request({
        url: url, method: "GET", timeout: 10,
        headers: { "User-Agent": "Mozilla/5.0", "Referer": "https://quote.eastmoney.com/" }
    });
    var o = JSON.parse(String(r.response_body));
    if (!o.data || !o.data.klines) throw "东财无数据";
    var kl = o.data.klines;
    var out = [];
    for (var i = 0; i < kl.length; i++) out.push(parseFloat(kl[i].split(",")[2]));  // 日期,开,收,高,低
    return out;
}

function kSina(code, period, n) {
    var scale = period === "week" ? 1200 : 240;
    var url = "https://money.finance.sina.com.cn/quotes_service/api/json_v2.php/CN_MarketData.getKLineData"
            + "?symbol=" + code + "&scale=" + scale + "&ma=no&datalen=" + n;
    var r = vflow.network.http_request({ url: url, method: "GET", timeout: 10 });
    var arr = JSON.parse(String(r.response_body));
    if (!arr || !arr.length) throw "新浪无数据";
    var out = [];
    for (var i = 0; i < arr.length; i++) out.push(parseFloat(arr[i].close));
    return out;
}

// ---------------- 主流程 ----------------
var out = {
    code: CODE, period: PERIOD, source: "", bars: 0,
    signal: "", trend: 0, prev: 0, close: 0, isNew: false, error: ""
};

var code = normCode(CODE);
var providers = [
    { name: "腾讯", fn: kTencent },
    { name: "东方财富", fn: kEastmoney },
    { name: "新浪", fn: kSina }
];

var closes = null;
for (var i = 0; i < providers.length; i++) {
    try {
        var k = providers[i].fn(code, PERIOD, BARS);
        if (k && k.length >= 40) { closes = k; out.source = providers[i].name; break; }
        out.error += providers[i].name + ":数据不足(" + (k ? k.length : 0) + "); ";
    } catch (e) {
        out.error += providers[i].name + ":" + String(e) + "; ";
    }
}

if (closes) {
    var e1 = ema(closes, 10);
    var e2 = ema(e1, 10);
    var n = e2.length;
    var cur = e2[n - 1], prev = e2[n - 2], prev2 = e2[n - 3];
    var up = cur > prev;
    var prevUp = prev > prev2;

    out.bars = closes.length;
    out.close = closes[closes.length - 1];
    out.trend = cur;
    out.prev = prev;
    out.signal = up ? "红/买" : "绿/卖";
    out.isNew = (up !== prevUp);

    var label = PERIOD === "week" ? "周线" : "日线";
    var shouldNotify = ONLY_NEW_SIGNAL ? out.isNew : true;

    if (shouldNotify) {
        vflow.notification.send_notification({
            title: code + " " + label + " 主趋势线" + (up ? "向上 · 买" : "向下 · 卖"),
            message: "主趋势线 " + cur.toFixed(3) + "（前值 " + prev.toFixed(3) + "）\n"
                   + "收盘 " + out.close + "\n"
                   + (out.isNew ? "★ 本根翻转" : "信号延续") + "\n"
                   + "数据源 " + out.source + " / " + out.bars + " 根"
        });
    }
} else {
    out.signal = "取数失败";
}

out;
